/**
 * Kumva StartCampaign Node with Embedded Webhook
 * Initializes campaign sessions, registers webhook, handles Africa's Talking callbacks
 */

module.exports = function(RED) {
  const { v4: uuidv4 } = require('uuid');
  const crypto = require('crypto');
  const SessionManager = require('kumva-insights/utils/session-manager');
  const DataStorage = require('kumva-insights/utils/data-storage');
  const ConfigManager = require('kumva-insights/utils/config-manager');
  const helpers = require('kumva-insights/utils/helpers');

  let globalSessionManager = null;
  let globalDataStorage = null;
  let globalConfigManager = null;
  const webhookManagers = new Map();
  const registeredPaths = new Set();

  async function initializeGlobals() {
    if (!globalSessionManager) {
      globalConfigManager = new ConfigManager();
      globalSessionManager = new SessionManager(globalConfigManager.getRedisConfig());
      await globalSessionManager.initialize();
      globalDataStorage = new DataStorage(globalConfigManager.getStoragePath());
    }
    return { sessionManager: globalSessionManager, dataStorage: globalDataStorage, configManager: globalConfigManager };
  }

  // Webhook manager: routes responses to correct waiting nodes by sessionId
  class WebhookManager {
    constructor() {
      this.nodeRegistry = new Map();
    }
    registerWaitingNode(sessionId, nodeInfo) {
      this.nodeRegistry.set(sessionId, nodeInfo);
    }
    unregisterWaitingNode(sessionId) {
      this.nodeRegistry.delete(sessionId);
    }
    getWaitingNode(sessionId) {
      return this.nodeRegistry.get(sessionId);
    }
    parseAfricasTalkingPayload(payload) {
      // SMS reply
      if (payload.text && payload.from) {
        return {
          type: 'sms',
          sessionId: payload.sessionId || payload.linkId,
          phoneNumber: payload.from,
          content: payload.text,
          timestamp: new Date().toISOString(),
          rawPayload: payload
        };
      }
      // Voice DTMF input
      if (payload.sessionId && (payload.dtmfInput || payload.durationInSeconds)) {
        return {
          type: 'dtmf',
          sessionId: payload.sessionId,
          phoneNumber: payload.callerNumber,
          content: payload.dtmfInput || '',
          timestamp: new Date().toISOString(),
          rawPayload: payload
        };
      }
      return null;
    }
    verifySignature(headers, body, apiKey) {
      if (!apiKey) return true;
      try {
        const signature = headers['x-africastalking-signature'];
        if (!signature) return false;
        const hash = crypto.createHmac('sha256', apiKey).update(body).digest('base64');
        return crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(hash));
      } catch (e) {
        return false;
      }
    }
  }

  // Register webhook endpoint for a flow
  function registerWebhookEndpoint(webhookPath, webhookManager, flowId) {
    if (registeredPaths.has(webhookPath)) return;
    registeredPaths.add(webhookPath);

    RED.httpAdmin.post(webhookPath, async (req, res) => {
      try {
        const { configManager, sessionManager } = await initializeGlobals();
        const payload = req.body;
        const apiKey = configManager.get('africasTalking.apiKey');

        if (!webhookManager.verifySignature(req.headers, JSON.stringify(payload), apiKey)) {
          RED.log.warn(`Invalid webhook signature at ${webhookPath}`);
        }

        const response = webhookManager.parseAfricasTalkingPayload(payload);
        if (!response) {
          return res.status(400).json({ success: false, error: 'Invalid payload' });
        }

        const sessionResult = await sessionManager.getSession(response.sessionId);
        if (!sessionResult.exists) {
          return res.status(404).json({ success: false, error: 'Session not found' });
        }

        // Route to waiting node via sessionId
        const waitingNode = webhookManager.getWaitingNode(response.sessionId);
        if (waitingNode && waitingNode.callback) {
          setImmediate(() => {
            waitingNode.callback(response);
          });
        }

        res.json({ success: true, sessionId: response.sessionId });
      } catch (error) {
        RED.log.error(`Webhook error: ${error.message}`);
        res.status(500).json({ success: false, error: error.message });
      }
    });
  }

  function KumvaStartCampaignNode(config) {
    RED.nodes.createNode(this, config);
    const node = this;
    const flowId = config.flowId || this.z;

    // Create webhook manager for this flow
    const webhookManager = new WebhookManager();
    webhookManagers.set(flowId, webhookManager);

    // Get webhook config
    const webhookPath = config.webhookPath || '/kumva/webhook';
    const baseUrl = process.env.KUMVA_WEBHOOK_BASE_URL || 'http://localhost:1880';
    const webhookUrl = baseUrl.replace(/\/$/, '') + webhookPath;

    // Register webhook endpoint
    registerWebhookEndpoint(webhookPath, webhookManager, flowId);

    // Export webhook manager globally for other nodes
    RED.nodes.getFlowWebhookManager = function(fid) {
      return webhookManagers.get(fid);
    };

    initializeGlobals().catch(error => {
      node.error(`Failed to initialize: ${error.message}`);
    });

    node.on('input', async function(msg) {
      try {
        const { sessionManager, dataStorage } = await initializeGlobals();

        if (!msg.phoneNumber || !msg.campaignId) {
          node.error('Missing phoneNumber or campaignId');
          return;
        }

        const sessionId = `session_${msg.campaignId}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
        const timeoutSeconds = helpers.timeToSeconds(config.sessionTimeout || '3600s');

        const sessionData = {
          sessionId: sessionId,
          phoneNumber: msg.phoneNumber,
          campaignId: msg.campaignId,
          campaignType: config.campaignType || 'sms',
          shortCode: config.shortCode || null,
          status: 'active',
          createdAt: new Date().toISOString(),
          contactData: msg.contactData || {},
          initialMessage: msg.initialMessage || '',
          webhookUrl: webhookUrl,
          debugMode: config.debugMode || false
        };

        const sessionResult = await sessionManager.createSession(sessionId, sessionData, timeoutSeconds);
        if (!sessionResult.success) {
          node.error(`Failed to create session: ${sessionResult.error}`);
          return;
        }

        if (config.storeResponses) {
          await dataStorage.createUserSession(msg.campaignId, msg.phoneNumber, sessionData);
        }

        const outputMsg = {
          ...msg,
          sessionId: sessionId,
          campaignStatus: 'initialized',
          webhookUrl: webhookUrl,
          _kumva: {
            ...msg._kumva,
            sessionId: sessionId,
            sessionTimeout: timeoutSeconds,
            webhookUrl: webhookUrl
          }
        };

        node.status({
          fill: 'green',
          shape: 'dot',
          text: `Session: ${sessionId.substring(0, 12)}...`
        });

        node.send(outputMsg);

      } catch (error) {
        node.error(`StartCampaign error: ${error.message}`);
        node.status({
          fill: 'red',
          shape: 'ring',
          text: 'Error'
        });
      }
    });

    node.on('close', function(done) {
      webhookManagers.delete(flowId);
      done();
    });

    node.status({
      fill: 'yellow',
      shape: 'ring',
      text: 'Ready'
    });
  }

  // Campaign report endpoint
  RED.httpAdmin.get('/kumva/campaign/:campaignId/report', async (req, res) => {
    try {
      const { dataStorage } = await initializeGlobals();
      const campaignId = req.params.campaignId;
      const sessionsResult = await dataStorage.getCampaignSessions(campaignId);

      if (!sessionsResult.success) {
        return res.status(500).json({ success: false, error: 'Failed to retrieve sessions' });
      }

      const sessions = sessionsResult.sessions || [];
      const summaries = sessions.map(session => ({
        sessionId: session.sessionId,
        phoneNumber: session.phoneNumber,
        responseCount: session.responses?.length || 0,
        status: session.metadata?.status || 'active',
        startedAt: session.metadata?.startedAt,
        completedAt: session.metadata?.lastUpdated
      }));

      res.json({
        campaignId: campaignId,
        generatedAt: new Date().toISOString(),
        summary: {
          totalSessions: summaries.length,
          completedSessions: summaries.filter(s => s.status === 'completed').length,
          totalResponses: summaries.reduce((sum, s) => sum + s.responseCount, 0)
        },
        sessions: summaries
      });
    } catch (error) {
      res.status(500).json({ success: false, error: error.message });
    }
  });

  RED.nodes.registerType('kumva-start-campaign', KumvaStartCampaignNode);
};